import { useState, useEffect, useMemo } from "react";
import { ExtendedDictionaryItem, DictionaryMeta } from "@/types/dictionary";

export function useDictionary() {
  const [aktifSozlukler, setAktifSozlukler] = useState<DictionaryMeta[]>([]);
  const [rawWords, setRawWords] = useState<ExtendedDictionaryItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [seciliLehce, setSeciliLehce] = useState<"TUMU" | "BATI" | "DOGU">("TUMU");
  const [seciliDosya, setSeciliDosya] = useState<string>("TUMU");

  useEffect(() => {
    let isMounted = true;

    async function loadData() {
      try {
        // 1. Manifest'i al
        const resManifest = await fetch("/data/dictionaries.json");
        const manifest: DictionaryMeta[] = await resManifest.json();
        if (!isMounted) return;
        setAktifSozlukler(manifest);

        // 2. Ana sözlükleri yükle
        const tumVeriler: ExtendedDictionaryItem[] = [];

        for (const meta of manifest) {
          try {
            const res = await fetch(`/data/${meta.file}`);
            if (!res.ok) continue;
            const raw = await res.json();
            const wordsObj = raw.words || raw;

            if (Array.isArray(wordsObj)) {
              for (const item of wordsObj) {
                const kelime = item.kelime || item.spelling;
                const tanim = item.tanim || (Array.isArray(item.definitions) ? item.definitions.join("; ") : "");
                if (kelime && tanim) {
                  tumVeriler.push({ kelime, tanim: String(tanim), file: meta.file, kaynak_sozluk: meta.title, dialect: meta.dialect });
                }
              }
            } else if (typeof wordsObj === "object" && wordsObj !== null) {
              for (const [key, val] of Object.entries(wordsObj)) {
                const tanim = typeof val === "string" ? val : (val as any)?.tanim || (val as any)?.meaning || "";
                if (tanim) {
                  tumVeriler.push({ kelime: key, tanim: String(tanim), file: meta.file, kaynak_sozluk: meta.title, dialect: meta.dialect });
                }
              }
            }
          } catch (e) {
            console.warn(`${meta.file} okunamadı, atlanıyor.`);
          }
        }

        if (isMounted) {
          setRawWords(tumVeriler);
          setLoading(false);
        }
      } catch (err) {
        console.error("Yükleme hatası:", err);
        if (isMounted) setLoading(false);
      }
    }

    loadData();
    return () => { isMounted = false; };
  }, []); // Bağımlılıklar boş: Sadece ilk açılışta 1 kez çalışır!

  const filtrelenmisSonuclar = useMemo(() => {
    let veri = rawWords;
    if (seciliLehce !== "TUMU") veri = veri.filter((i) => i.dialect === seciliLehce);
    if (seciliDosya !== "TUMU") veri = veri.filter((i) => i.file === seciliDosya);
    
    const q = searchQuery.trim().toLowerCase();
    if (q) {
      veri = veri.filter(
        (i) => i.kelime.toLowerCase().includes(q) || i.tanim.toLowerCase().includes(q)
      );
    }
    return veri;
  }, [rawWords, seciliLehce, seciliDosya, searchQuery]);

  const gununKelimesi = rawWords.length > 0 ? rawWords[0] : null;

  return {
    wordsCount: rawWords.length,
    loading,
    searchQuery,
    setSearchQuery,
    seciliLehce,
    setSeciliLehce,
    seciliDosya,
    setSeciliDosya,
    gununKelimesi,
    filtrelenmisSonuclar,
    aktifSozlukler,
  };
}